import json
from pathlib import Path
import numpy as np
from PIL import Image
from lucas_kanade_icgn import ICGNWGPUFullPyramid

class EmptyPass:
 def set_pipeline(self,*args): pass
 def set_bind_group(self,*args): pass
 def dispatch_workgroups(self,*args): pass
 def end(self): pass
class Encoder:
 def __init__(self,owner,actual): self.owner,self.actual=owner,actual; self.number=0
 def __getattr__(self,name): return getattr(self.actual,name)
 def begin_compute_pass(self,**kwargs):
  self.number+=1
  return self.actual.begin_compute_pass(**kwargs) if self.number <= self.owner.limit else EmptyPass()
class Device:
 def __init__(self,actual): self.actual=actual; self.limit=13
 def __getattr__(self,name): return getattr(self.actual,name)
 def create_command_encoder(self,**kwargs): return Encoder(self,self.actual.create_command_encoder(**kwargs))

root=Path('/home/jeff/Code/tests_gpuio/DIC/LucasKanadeICGN')
reference=np.array(Image.open(root/'assets/uhd_tensile/reference.png'))
target=np.array(Image.open(root/'assets/uhd_tensile/frame_040.png'))
data=[]
with ICGNWGPUFullPyramid(initialization='temporal',device_type='gpu',outlier_policy='median') as e:
 e.set_reference(reference)
 for _ in range(20): e.register(target)
 proxy=Device(e.device); e.device=proxy
 for campaign in range(2):
  for limit in list(range(14))[::(-1 if campaign else 1)]:
   proxy.limit=limit
   for _ in range(3): e.register(target)
   samples=[]
   for _ in range(20): samples.append(e.register(target).timing['executeReadbackWallMs'])
   data.append({'campaign':campaign,'prefix_passes':limit,'execute_readback_ms':samples,'median_ms':float(np.median(samples))})
   print(campaign,limit,round(float(np.median(samples)),3),flush=True)
Path('/tmp/temporal-prefix-ablation.json').write_text(json.dumps(data,indent=2))

