import json
import runpy
import sys
import threading
import time
from pathlib import Path

rows=[]; done=threading.Event()
paths={
 'gpu_mhz':'/sys/class/drm/card1/device/tile0/gt0/freq0/act_freq',
 'requested_mhz':'/sys/class/drm/card1/device/tile0/gt0/freq0/cur_freq',
 'throttle':'/sys/class/drm/card1/device/tile0/gt0/freq0/throttle/reasons',
 'cpu_millidegrees':'/sys/class/thermal/thermal_zone0/temp',
}
def sample():
 while not done.is_set():
  row={'time':time.perf_counter()}
  for key,p in paths.items():
   try: row[key]=Path(p).read_text().strip()
   except OSError: row[key]=None
  rows.append(row); done.wait(.02)
t=threading.Thread(target=sample); t.start()
try: runpy.run_path('/tmp/measure_temporal_ab.py',run_name='__main__')
finally:
 done.set();t.join()
 Path(sys.argv[2]+'.telemetry.json').write_text(json.dumps(rows,indent=2))
